Webpack 5 Features:
module.exports = {
  // Asset modules replace file-loader/url-loader
  module: {
    rules: [
      { test: /\.(png|jpg)$/i, type: 'asset' },
      { test: /\.svg$/, type: 'asset/resource' },
      { test: /\.txt$/, type: 'asset/source' }
    ]
  },
  // Built-in asset modules handle most file types
  // No need for raw-loader, file-loader, or url-loader
};

